// CSD_RATIONALE_BEGIN
// Core finding: attempt 2 (40.8%, 81.6%) is the best so far.
// Attempt 14 added EOS rescue and changed guidance to prohibit comparison operators;
// it regressed to 34.7%/69.4%.
//
// Root cause analysis of attempt 14 regression:
//   1. Guidance prohibition of `==`, `!=`, `>`, `<` appears to confuse the model's
//      reasoning, making intermediate steps less reliable.
//   2. SafeRepetitionPenaltyStep(4.0) penalizes valid symbolic tokens (e.g. `n1`,
//      `*`, `c1`) that MUST repeat across spans in symbolic math. This pushes the
//      model toward EOS prematurely inside spans.
//   3. `**` in guidance triggers the model to try exponentiation, but `**` is NOT
//      in the arithmetic grammar (final_span_invalid mentions `**`), causing parser
//      rejection and fallback to EOS.
//
// Targeted fixes:
//   A. Replace SafeRepetitionPenaltyStep with ConstrainedStep (pure hard mask).
//      Inside constrained spans the hard mask already blocks `!` and all invalid
//      tokens; the repetition penalty is therefore harmful (it penalises variable
//      names that legitimately repeat across intermediate spans) and unnecessary.
//   B. Remove `**` from task guidance (not in the grammar).
//   C. Add "always wrap the final answer in int()" — the most common wrong-answer
//      pattern is the correct formula without int() wrapping.
//   D. Keep structure from attempt 2 (closeReserve=80, final cleanup, no EOS rescue).
//      Attempt 14 proved EOS rescue is not net-positive.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 — parser_validity:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   (remaining <= closeReserve, inside span — CloseSpanWithinBudget):
//     Postcondition: insideOut ==> parser.IsValidPrefix(currentOut).
//     Closed path (ci=false): implication vacuous. Open path: direct postcondition. ✓
//
//   (outside span — UnconstrainedStep):
//     If RenderedEndsWith triggers, set currentConstrainedOut := [];
//     parser.IsValidPrefix([]) holds by the method precondition (parser.IsValidPrefix([])).
//     Otherwise insideConstrainedOut stays false (vacuous). ✓
//
//   (IsCompletePrefix branch — CloseConstrainedSpan):
//     Sets insideConstrainedOut := false; implication vacuously true. ✓
//
//   (constrained step, non-EOS — ConstrainedStep + AppendConstrainedToken):
//     ConstrainedStep hard-masks to parser-valid tokens plus EOS; non-EOS return
//     is therefore parser-valid next. AppendConstrainedToken postcondition:
//     parser.IsValidPrefix(currentOut). ✓
//
//   (constrained step, EOS — break):
//     Neither generated nor currentConstrainedOut is changed; invariant preserved. ✓
//
//   (final cleanup — CloseSpanWithinBudget):
//     Same argument as the closeReserve branch. ✓
//
// Invariant 2 — progress:
//   |generated| <= |generatedPrefix| + steps
//
//   (remaining <= closeReserve, s = steps_before):
//     CloseSpanWithinBudget(remaining): |cg| <= |generated| + remaining
//       <= |generatedPrefix| + s + (maxSteps - s) = |generatedPrefix| + maxSteps.
//     After steps := maxSteps: |generated| <= |generatedPrefix| + steps. ✓
//
//   (outside span): steps grows by 1; at most one token appended to generated. ✓
//
//   (IsCompletePrefix branch): steps grows by 1; CloseConstrainedSpan appends
//     at most one ">>" token to generated. ✓
//
//   (constrained step, non-EOS): steps grows by 1; AppendConstrainedToken appends
//     exactly one token. |generated| increases by 1, steps increases by 1. ✓
//
//   (constrained step, EOS): steps grows by 1; generated unchanged (break).
//     |generated| <= |generatedPrefix| + (steps - 1) < |generatedPrefix| + steps. ✓
//
//   (final cleanup, s = steps):
//     |cg| <= |generated| + (maxSteps - s) <= |generatedPrefix| + s + maxSteps - s
//       = |generatedPrefix| + maxSteps.
//     steps := maxSteps: |generated| <= |generatedPrefix| + maxSteps = |generatedPrefix| + steps. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve the problem step by step. " +
  "Wrap every intermediate symbolic expression in << >> delimiters. " +
  "For the final answer, write: The final answer is <<symbolic expression>>. " +
  "Inside << >> use ONLY: numbers, problem variables, +, -, *, /, //, %, (), int(). " +
  "Always wrap the final answer expression in int() to ensure a whole number result. " +
  "Use // for integer (floor) division. " +
  "Use the exact variable names given in the problem — never substitute numbers for variables. " +
  "Do not write if/else, comparisons, or conditional expressions inside << >>. " +
  "Keep each << >> expression short and direct.");

var closeReserve: nat := 80;
var steps: nat := 0;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var remaining: nat := maxSteps - steps;

  if insideConstrainedOut && remaining <= closeReserve {
    // Budget running low inside a span: force-close with dead-end-aware helper
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, remaining
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := maxSteps;
    break;
  } else if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      generated := generated + [next];
      if RenderedEndsWith(generated, "<<") {
        insideConstrainedOut := true;
        currentConstrainedOut := [];
      }
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    var cg, ci, cc := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
  } else {
    // Pure hard-mask constrained step: no repetition penalty.
    // The repetition penalty hurts symbolic math because variable names
    // (n1, c1, etc.) legitimately repeat across multiple spans.
    // The hard mask already prevents all invalid tokens including `!`.
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := helpers.ConstrainedStep(lm, parser, constrainedPrompt, currentConstrainedOut, eosToken);
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      var ag, ai, ac := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := ag;
      insideConstrainedOut := ai;
      currentConstrainedOut := ac;
    }
  }
}

// Final cleanup: close any remaining open span with whatever budget is left
if insideConstrainedOut && steps < maxSteps {
  var remaining: nat := maxSteps - steps;
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, remaining
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := maxSteps;
}

cost := steps;

